    // the second array list is an array array list of integers. Use the two given array lists to build the algebric 
    // expression and return the evaluation of this expression.
    // The basic algebra operations:
    // Addition ( + ) 
    // Subtraction ( - ) 
    // Multiplication ( * ) 
    // Floor division ( // ) 
    // Exponentiation ( ** ) 
    // Example:
    // operator['+', '*', '-']
    // array array list = [2, 3, 4, 5]
    // result = 2 + 3 * 4 - 5
    // => result = 9
    // Note:
    // The length of operator array list is equal to the length of operand array list minus one.
    // Operand is an array array list of of non-negative integers.
    // Operator array list has at least one operator, and operand array list has at least two operands.
    public static long doAlgebra(ArrayList<String> op, ArrayList<Long> operand) {
// Process in order: **, then *, //, then +, -
        // We need to evaluate respecting operator precedence
        // But looking at the example: 2 + 3 * 4 - 5 = 9
        // 3 * 4 = 12, 2 + 12 = 14, 14 - 5 = 9
        // So we do respect precedence

        ArrayList<String> operators = new ArrayList<>(op);
        ArrayList<Long> operands = new ArrayList<>(operand);

        // First pass: exponentiation (**)
        for (int i = 0; i < operators.size(); i++) {
            if (operators.get(i).equals("**")) {
                long result = (long) Math.pow(operands.get(i), operands.get(i + 1));
                operands.set(i, result);
                operands.remove(i + 1);
                operators.remove(i);
                i--;
            }
        }

        // Second pass: multiplication and floor division
        for (int i = 0; i < operators.size(); i++) {
            if (operators.get(i).equals("*") || operators.get(i).equals("//")) {
                long result;
                if (operators.get(i).equals("*")) {
                    result = operands.get(i) * operands.get(i + 1);
                } else {
                    result = operands.get(i) / operands.get(i + 1);
                }
                operands.set(i, result);
                operands.remove(i + 1);
                operators.remove(i);
                i--;
            }
        }

        // Third pass: addition and subtraction
        for (int i = 0; i < operators.size(); i++) {
            if (operators.get(i).equals("+") || operators.get(i).equals("-")) {
                long result;
                if (operators.get(i).equals("+")) {
                    result = operands.get(i) + operands.get(i + 1);
                } else {
                    result = operands.get(i) - operands.get(i + 1);
                }
                operands.set(i, result);
                operands.remove(i + 1);
                operators.remove(i);
                i--;
            }
        }

        return operands.get(0);
    }
    public static void main(String[] args) {
    assert(doAlgebra((new ArrayList<String>(Arrays.asList((String)"**", (String)"*", (String)"+"))), (new ArrayList<Long>(Arrays.asList((long)2l, (long)3l, (long)4l, (long)5l)))) == (37l));
